@startuml

class Car {
  + licensePlate : string
  + model : string
  + capacity : int
}

class SoberCar {
  + isOwnedBySober : boolean
}

class CarOwner {
  + name : string
  + phoneNumber : string
}

class Customer {
  + name : string
  + phoneNumber : string
}

class RideHailService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : float
  + distance : float
  + passengerCount : int
  + fee : float
  + requestType : RequestType
}

class RideShareService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : float
  + distance : float
  + negotiatedFee : float
}

class Accident {
  + date : date
  + location : string
  + damageAmount : float
}

enum RequestType {
  SoberApp
  HandWaving
}

SoberCar --|> Car
CarOwner "1" -- "0..*" SoberCar : owns
Customer "1" -- "0..*" RideHailService : initiates
Customer "1" -- "0..*" RideShareService : books

RideHailService "*" -- "1" SoberCar : uses
RideShareService "*" -- "1" SoberCar : uses

RideHailService "1" -- "1..*" Customer : passengers
RideShareService "1" -- "1..*" Customer : passengers

SoberCar "1" *-- "0..*" Accident
@enduml

